[
  {
    "title": "Before You Build",
    "content": "- Define your goal: what should this website DO? (Get calls, book jobs, sell products)\n- Know your customer: who are you trying to reach, and what are they searching for?\n- Claim your Google Business Profile and verify it — this is step one for local SEO\n- Choose a domain that's short, brandable, and matches your business name\n- Decide on hosting and who owns the domain — you should always own both"
  },
  {
    "title": "Content You'll Need",
    "content": "- Clear, honest copy that speaks to your customer's problem\n- Real photos of your work — not stock photos\n- Your exact service area and the neighborhoods you serve\n- Contact info that's identical everywhere: website, Google, directories\n- Reviews: gather at least 5 before you launch, and keep collecting"
  },
  {
    "title": "Design That Converts",
    "content": "- One clear call-to-action above the fold: Call Now, Book Now, or Get a Quote\n- Mobile-first: most local searches happen on phones\n- Click-to-call button visible at all times on mobile\n- Fast loading — every second of delay costs you visitors\n- Trust signals: licenses, credentials, before/after photos, testimonials"
  },
  {
    "title": "Before You Go Live",
    "content": "- Test the site on real phones, not just desktop\n- Check every link and form\n- Set up Google Analytics and Google Search Console\n- Add local schema markup so Google understands your business\n- Write a privacy policy and terms page"
  },
  {
    "title": "After Launch",
    "content": "- Submit your site to Google Search Console and request indexing\n- Keep your Google Business Profile updated with new photos and posts\n- Ask every happy customer for a review\n- Track which pages get traffic and which pages get calls\n- Plan regular updates — a website is an asset, not a one-time expense"
  }
]

[
  {
    "title": "What These Are",
    "content": "A set of **doodle concepts** for approval — simple, charming, hand-drawn-feel sketches to support the Snow Beats 'Download Loop' feature and general SnowSnakes vibe.\n\nThese are **visual briefs**: a designer/artist (or ClickClack in the build) can render them from these descriptions. Each has a name, what it looks like, and where it goes."
  },
  {
    "title": "Doodle 1 — The Loop Drop (download mascot)",
    "content": "**Look:** A chubby cassette tape with a chunky download arrow pointing down into a little music note. Hand-drawn black outline, off-white fill, one accent color (icy blue #7FD1FF). Friendly, round, slightly tilted.\n**Where:** Download Loop button icon + success toast decoration.\n**Vibe:** 'Your beat, saved. Cute and clear.'"
  },
  {
    "title": "Doodle 2 — Snow Beats Snowman DJ",
    "content": "**Look:** A small snowman wearing oversized headphones, one hand raised like a DJ scratch, standing behind two tiny toy decks. Black outline, icy blue + white, red scarf accent.\n**Where:** Snow Beats loading screen, game corner watermark.\n**Vibe:** 'Music in the snow, beat-making energy.'"
  },
  {
    "title": "Doodle 3 — The Wave Loop",
    "content": "**Look:** A looping audio waveform drawn as a continuous circle of bumpy lines (like a sound wave that loops back on itself), with a small play triangle inside and a tiny music note on the outside.\n**Where:** Empty-state illustration when no beat is playing.\n**Vibe:** 'Loop it forever — simple, musical.'"
  },
  {
    "title": "Doodle 4 — Rat King mini (Snitch cross-promo)",
    "content": "**Look:** Tiny smug rat king with a crown, holding a little cassette like a trophy. Two colors: warm gray rat + gold crown. Hand-drawn, minimalist, big eyes.\n**Where:** 'Download & share your loop' prompt, cross-game nod to Snitch.\n**Vibe:** 'Even the Rat King approves your beat.'"
  },
  {
    "title": "Doodle 5 — The Boom Box Rat",
    "content": "**Look:** A rat balancing a vintage boombox on its head, music notes floating up. Black outline, warm gray + red boombox accents.\n**Where:** Snow Beats share card, footer mascot.\n**Vibe:** 'Portable beats, rat-approved.'"
  },
  {
    "title": "Doodle 6 — Icy Cassette (Spread Da Word nod)",
    "content": "**Look:** A cassette with an icy blue snowflake on the label and a little frozen drip. Retro tape shape, two spools showing.\n**Where:** 'Switch tapes' easter egg, soundtrack player references inside Snow Beats.\n**Vibe:** 'Icy mode, cold beats — on-brand crossover.'"
  }
]

